def R(cid, **kw):
    base = {"case_id": cid, "status": "Optimal", "objective": None, "sense": "max",
            "model_file": f"models/{cid}.py", "output_file": f"models/{cid}.out.txt", "solver": "PULP_CBC_CMD",
            "model_summary": "", "integrality_ambiguous": False, "integer_relaxed_objective": None,
            "asked_value": None, "issue": "NONE", "issue_note": "", "readings": [], "confidence": "HIGH",
            "problem_type": None, "type_after_linearization": None, "type_rationale": "", "type_confidence": None, "notes": ""}
    base.update(kw); return base
